def small_flower(cx, cy, r=7, c='f-pink'):
    return ''.join(f'<ellipse cx="{cx}" cy="{cy-r}" rx="{r*.62:.1f}" ry="{r}" class="{c}" transform="rotate({a} {cx} {cy})"/>' for a in range(0, 360, 72)) + f'<circle cx="{cx}" cy="{cy}" r="{r*.38:.1f}" class="f-gold"/>'

def tiny_sun(cx, cy, r=4):
    return f'<circle cx="{cx}" cy="{cy}" r="{r}" class="f-gold"/>'

